using StackExchange.Redis;

public class LeaderboardService
{
    private readonly IDatabase _db;
    private const string LeaderboardKey = "leaderboard:global";

    public LeaderboardService(IConnectionMultiplexer redis)
    {
        _db = redis.GetDatabase();
    }

    public async Task UpdateScoreAsync(string playerId, double score)
    {
        await _db.SortedSetAddAsync(LeaderboardKey, playerId, score);
    }

    public async Task<IList<LeaderboardEntry>> GetTopAsync(int count)
    {
        var entries = await _db.SortedSetRangeByRankWithScoresAsync(
            LeaderboardKey, 0, count - 1, Order.Descending);

        return entries.Select((e, index) => new LeaderboardEntry
        {
            Rank = index + 1,
            PlayerId = (string)e.Element!,
            Score = e.Score
        }).ToList();
    }

    public async Task<int?> GetPlayerRankAsync(string playerId)
    {
        var rank = await _db.SortedSetRankAsync(
            LeaderboardKey, playerId, Order.Descending);
        return rank.HasValue ? (int)(rank.Value + 1) : null;
    }
}

public class LeaderboardEntry
{
    public int Rank { get; set; }
    public string PlayerId { get; set; } = string.Empty;
    public double Score { get; set; }
}

const Redis = require('ioredis');
const redis = new Redis();
const LEADERBOARD = 'leaderboard:global';

async function updateScore(playerId, score) {
  await redis.zadd(LEADERBOARD, score, playerId);
}

async function getTop(count) {
  const entries = await redis.zrevrange(LEADERBOARD, 0, count - 1, 'WITHSCORES');
  const result = [];
  for (let i = 0; i < entries.length; i += 2) {
    result.push({ rank: i / 2 + 1, playerId: entries[i], score: parseFloat(entries[i + 1]) });
  }
  return result;
}

async function getPlayerRank(playerId) {
  const rank = await redis.zrevrank(LEADERBOARD, playerId);
  return rank !== null ? rank + 1 : null;
}

// Example usage
(async () => {
  await updateScore('player-1', 1500);
  await updateScore('player-2', 2200);
  console.log(await getTop(10));
  console.log('Player 1 rank:', await getPlayerRank('player-1'));
})();
